  /* Video Lessons page: course type → subject → major → unit. */
  function videoSubjectType(subject,subjectEntries){
    const source=[subject.id,subject.name,...subjectEntries.map(({item})=>[item.resource.major,item.resource.unit,item.resource.title].filter(Boolean).join(' '))].join(' ').toLowerCase();
    if(/\bsec\b|skill enhancement/.test(source))return'sec';
    if(/\boe\b|open elective/.test(source))return'oe';
    if(/(^|\W)(aec|vec|iks)(\W|$)|common subjects/.test(source))return'common';
    if(/geography|french|other subjects/.test(source))return'other';
    return'major';
  }
