    const typeGroups=groups.filter(group=>group.type===videoActiveType).sort((a,b)=>{const order=subjectOrderByType[videoActiveType]||[];const rank=name=>{const key=String(name||'').toLowerCase().replace(/[^a-z0-9]/g,'');const index=order.findIndex(item=>key===item.toLowerCase().replace(/[^a-z0-9]/g,'')||key.startsWith(item.toLowerCase().replace(/[^a-z0-9]/g,''))||item.toLowerCase().replace(/[^a-z0-9]/g,'').startsWith(key));return index<0?999:index};return rank(a.subject.name)-rank(b.subject.name)||String(a.subject.name).localeCompare(String(b.subject.name))});
    const availableSubjects=[...typeGroups.map(group=>group.subject.id),...(subjectOrderByType[videoActiveType]||[]).map(name=>'library-'+String(name).toLowerCase().replace(/[^a-z0-9]/g,''))];if(videoActiveSubject!=='all'&&!availableSubjects.includes(videoActiveSubject))videoActiveSubject='all';if(videoActiveSubject==='all'&&typeGroups.length)videoActiveSubject=typeGroups[0].subject.id;
